export async function handle(db, request) {
  await db.lock("stock-lock");
  try {
    const orders = await db.get("orders");
    if (Array.isArray(orders)) {
      for (const o of orders) {
        if (o && o.requestId === request.id) {
          return { accepted: true };
        }
      }
    }
    const available = await db.get("stock");
    if (available < request.quantity) {
      return { accepted: false };
    }
    await db.set("stock", available - request.quantity);
    await db.append("orders", {
      requestId: request.id,
      quantity: request.quantity
    });
    return { accepted: true };
  } finally {
    await db.unlock("stock-lock");
  }
}

